# ---------------------------------------------------------------- generate blocks
def _items(pairs):
    return [{"q": q, "a": list(a), "ok": ok, "why": why} for q, a, ok, why in pairs]


def _blocks():
    total = sum(len(d["items"]) for d in DOMAINS) + len(CONSOL)
    rows = [[d["code"], d["title"], str(len(d["items"])), _CHAPTER[d["code"]]] for d in DOMAINS]
    rows.append(["K", "Consolidated mock exam (cross-chapter)", str(len(CONSOL)), "All chapters"])
    bl = [
        {"t": "lead", "x": ("The questions follow SAP MM's knowledge structure: 10 domains plus one cross-chapter consolidated paper, %d questions in total. " % total) +
                          "Four options each, exactly one correct; every answer is scored immediately, with the explanation and the reasoning behind it. Get a question wrong and the fastest fix is to go back to that chapter and re-read the table."},
        {"t": "h2", "x": "How to use this test"},
        {"t": "ul", "cls": "fld", "items": [
            "**Work domain by domain**: 8 to 12 questions per domain, then read the explanations; two or more wrong and you should re-read that chapter's key points.",
            "**Then take the consolidated paper**: those are scenario questions, testing where you look first rather than definitions.",
            "**Check the total last**: the progress bar (right/top) is the site-wide running accuracy and resets on refresh (nothing is written to localStorage).",
            "**Do not memorise answers**: the same fact is asked in different ways across questions (GR/IR, for instance, appears both as a journal entry and as a balance question).",
        ]},
        {"t": "table",
         "head": ["Domain", "Coverage", "Questions", "Chapter"],
         "rows": rows},
        {"t": "raw", "x": '<div class="totbar"><b>Site score</b><span id="quizTotal">0 / ' + str(total) +
                          '</span><span class="bar"><i id="quizBar"></i></span></div>'},
    ]
    for d in DOMAINS:
        bl.append({"t": "h2", "x": "%s. %s (%d questions)" % (d["code"], d["title"], len(d["items"]))})
        bl.append({"t": "ul", "cls": "fld", "items": d["tips"]})
        bl.append({"t": "quiz", "cat": d["code"], "items": _items(d["items"])})
    bl.append({"t": "h2", "x": "K. Consolidated mock exam (%d questions)" % len(CONSOL)})
    bl.append({"t": "p", "x": "The questions below are no longer grouped by chapter; all of them are the \"what would you do on the spot\" kind: where do you look first when the error appears, which two lines moved in the books, does this step create a document."})
    bl.append({"t": "quiz", "cat": "K", "items": _items(CONSOL)})
    bl.append({"t": "dl", "href": "{root}downloads/MM-quiz-bank.xlsx",
               "x": "Download the Excel question bank (126 questions with options, answers, explanations, answer sheet and per-domain stats)"})
    bl.append({"t": "note", "kind": "ok", "b": "How scoring works",
               "x": "Only the first click on each question counts, and a wrong choice still shows the correct answer with its explanation (good for learning, not for a closed-book exam). "
                    "For a closed-book run, zoom the browser out below 100% and do it once, then come back to the explanations; or print the page (A4 portrait) and use it as a paper test."})
    return bl


